1	// Shared VPS order core — used by the wallet flow (lib/actions.ts orderServer),
2	// the direct-pay flow (payAndDeploy), and the Stripe confirm route so a paid
3	// checkout can provision immediately. Plain server module (not "use server").
4	import { z } from "zod";
5	import type { User } from "@prisma/client";
6	import { db } from "./db";
7	import { debitWallet, InsufficientBalanceError } from "./wallet";
8	import { vpsTerm, vpsTermPriceCents, addMonths } from "./billing-terms";
9	import { DEDICATED_IP_PRICE_CENTS } from "./dedicated-ip";
10	import { capacityCheck, diskCapacityCheck } from "./capacity";
11	import { invoiceCreateData } from "./invoices";
12	import { maybeRewardReferral } from "./actions-growth";
13	import { currentPromo, promoPriceCents } from "./promotions";
14	
15	export class OrderError extends Error {}
16	
17	export const orderSchema = z.object({
18	  planId: z.string().min(1),
19	  osTemplateId: z.string().min(1),
20	  hostname: z
21	    .string()
22	    .min(3)
23	    .max(40)
24	    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
25	});
26	
27	export type OrderIntent = {
28	  planId: string;
29	  osTemplateId: string;
30	  hostname: string;
31	  nodeId?: string;
32	  addonMalware?: boolean;
33	  addonBackup?: boolean;
34	  addonDocker?: boolean;
35	  termMonths?: number;
36	  dedicatedIp?: boolean;
37	  sshPublicKey?: string;
38	  sshKeyName?: string;
39	  free?: boolean;
40	};
41	
42	/** Extract a plain OrderIntent from a deploy form. */
43	export function intentFromFormData(formData: FormData): OrderIntent {
44	  return {
45	    planId: String(formData.get("planId") ?? ""),
46	    osTemplateId: String(formData.get("osTemplateId") ?? ""),
47	    hostname: String(formData.get("hostname") ?? ""),
48	    nodeId: String(formData.get("nodeId") ?? "") || undefined,
49	    addonMalware: formData.get("addon_malware") === "1",
50	    addonBackup: formData.get("addon_backup") === "1",
51	    addonDocker: formData.get("addon_docker") === "1",
52	    termMonths: Number(formData.get("termMonths") ?? 1),
53	    dedicatedIp: formData.get("dedicatedIp") === "1",
54	    sshPublicKey: String(formData.get("sshPublicKey") ?? "").trim() || undefined,
55	    sshKeyName: String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60),
56	    free: formData.get("free") === "1",
57	  };
58	}
59	
60	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
61	async function scheduleNode(planRamMB: number) {
62	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
63	  if (nodes.length === 0) return null;
64	  const loads = await Promise.all(
65	    nodes.map(async (n) => {
66	      const agg = await db.server.findMany({
67	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
68	        select: { plan: { select: { ramMB: true } } },
69	      });
70	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
71	      return { node: n, free: n.capacityRamMB - used };
72	    }),
73	  );
74	  loads.sort((a, b) => b.free - a.free);
75	  return loads[0].node;
76	}
77	
78	/** Validate + price an order without placing it. Throws OrderError on any problem. */
79	export async function orderQuote(intent: OrderIntent) {
80	  const parsed = orderSchema.safeParse(intent);
81	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
82	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
83	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
84	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
85	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
86	    throw new OrderError(
87	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
88	    );
89	  }
90	  const term = vpsTerm(Number(intent.termMonths ?? 1));
91	  const ipCents = intent.dedicatedIp ? DEDICATED_IP_PRICE_CENTS * term.months : 0;
92	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
93	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
94	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
95	  // real renewal price and this discounted value is the real first-term price.
96	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
97	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
98	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);
99	  const promo = currentPromo(new Date());
100	  const planFirstTermCents = promoPriceCents(regularPlanCents, promo);
101	  const chargeCents = planFirstTermCents + ipCents;
102	  return { plan, os, term, chargeCents, promo, regularPlanCents };
103	}
104	
105	/**
106	 * Place an order: validate, charge the wallet (unless a free admin grant),
107	 * create the Server + PROVISION job. Returns the new server id. Does NOT
108	 * redirect. Callers must ensure funds exist (or pass free) — this still
109	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
110	 */
111	export async function placeOrder(user: User, intent: OrderIntent): Promise<string> {
112	  const { plan, os, term, chargeCents, promo } = await orderQuote(intent);
113	  // Note the intro discount on the billing document (first term only; renews full).
114	  const promoNote = promo.discountPercent > 0 ? ` · ${promo.name} ${promo.discountPercent}% off first term` : "";
115	
116	  const cap = await capacityCheck(plan.id);
117	  if (!cap.ok) throw new OrderError(cap.reason);
118	
119	  let nodeId: string | null = null;
120	  if (intent.nodeId) {
121	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
122	    if (!n) throw new OrderError("Selected location is not available.");
123	    nodeId = n.id;
124	  } else {
125	    const n = await scheduleNode(plan.ramMB);
126	    nodeId = n?.id ?? null;
127	  }
128	
129	  const diskCap = await diskCapacityCheck(nodeId, plan.diskGB);
130	  if (!diskCap.ok) throw new OrderError(diskCap.reason);
131	
132	  const addons = {
133	    malwareScanner: !!intent.addonMalware,
134	    dailyBackup: !!intent.addonBackup,
135	    docker: !!intent.addonDocker,
136	  };
137	  const isAdmin = user.role === "ADMIN";
138	  const freeRequested = !!intent.free && isAdmin;
139	  if (!freeRequested && user.balanceCents < chargeCents) throw new OrderError("Insufficient balance.");
140	
141	  const newKey = (intent.sshPublicKey ?? "").trim();
142	  const keyName = (intent.sshKeyName ?? "deploy-key").slice(0, 60);
143	
144	  let server;
145	  try {
146	    server = await db.$transaction(async (tx) => {
147	      if (!freeRequested) {
148	        await debitWallet(tx, user.id, chargeCents);
149	        await tx.walletTransaction.create({
150	          data: {
151	            userId: user.id,
152	            amountCents: -chargeCents,
153	            description: `Order: ${plan.name} VPS (${intent.hostname}) — ${term.label}${promoNote}`,
154	          },
155	        });
156	        // Billing document for the charge — created inside the same debit tx so it
157	        // shares the transaction's atomicity (a rolled-back charge leaves no invoice).
158	        const lineDesc = `${plan.name} VPS (${intent.hostname}) — ${term.label}${promoNote}`;
159	        await tx.invoice.create({
160	          data: invoiceCreateData({
161	            userId: user.id,
162	            description: lineDesc,
163	            status: "PAID",
164	            period: { start: new Date(), end: addMonths(new Date(), term.months) },
165	            lineItems: [{ description: lineDesc, qty: 1, unitCents: chargeCents, amountCents: chargeCents }],
166	          }),
167	        });
168	      }
169	      if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
170	        const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
171	        if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
172	      }
173	      const s = await tx.server.create({
174	        data: {
175	          name: intent.hostname,
176	          hostname: intent.hostname,
177	          userId: user.id,
178	          planId: plan.id,
179	          osTemplateId: os.id,
180	          nodeId,
181	          addons,
182	          termMonths: term.months,
183	          wantsDedicatedIp: !!intent.dedicatedIp,
184	          isFree: freeRequested,
185	          expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
186	        },
187	      });
188	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
189	      return s;
190	    });
191	  } catch (e) {
192	    if (e instanceof InsufficientBalanceError) throw new OrderError("Insufficient balance.");
193	    throw e;
194	  }
195	
196	  await db.auditLog.create({
197	    data: {
198	      userId: user.id,
199	      action: "server.order",
200	      detail: `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo free=${freeRequested}`,
201	    },
202	  });
203	  if (!freeRequested) {
204	    try {
205	      await maybeRewardReferral(user.id);
206	    } catch {
207	      /* non-fatal */
208	    }
209	  }
210	  return server.id;
211	}
