1	/**
2	 * Seasonal / promotional pricing — HONEST intro-discount model.
3	 *
4	 * The whole design is an INTRO DISCOUNT: a promo discounts a customer's FIRST
5	 * TERM only. The "regular" (strikethrough) price is the genuine renewal price;
6	 * the "promo" price is the genuine first-term price. BOTH are real charges —
7	 * never a fabricated former price and never a bait-and-switch. The discounted
8	 * price shown must equal what checkout charges (see promoPriceCents usage in
9	 * lib/order.ts, lib/actions.ts and lib/actions-email-hosting.ts). Renewal paths
10	 * (worker/billing.ts, worker/product-renewals.ts) are left untouched, so
11	 * renewals bill the regular price — exactly what the strikethrough promises.
12	 *
13	 * Countdowns use promoEndsAt(), which returns the promo window's REAL close
14	 * date. Promos genuinely rotate by calendar date; a new one may begin after the
15	 * current one ends, but the current one truly ends when the timer says.
16	 *
17	 * Pure & deterministic: every helper takes `now` as a parameter. Nothing here
18	 * calls Date.now() at module load, so it is safe to import anywhere (including
19	 * server components that render it at request time).
20	 */
21	
22	export type Promo = {
23	  id: string;
24	  /** Full name, e.g. "Summer Sale". */
25	  name: string;
26	  /** Short badge text, e.g. "Summer Sale". */
27	  label: string;
28	  /** Percent off the FIRST-term charge (0–100). */
29	  discountPercent: number;
30	  /** Window open, inclusive, "MM-DD". */
31	  start: string;
32	  /** Window close, inclusive, "MM-DD" (may wrap the year end). */
33	  end: string;
34	};
35	
36	/**
37	 * Rotating seasonal promos. Checked in array order; the first promo whose
38	 * calendar window covers `now` wins. Windows are real dates — the countdown a
39	 * customer sees is the true close of the active window.
40	 */
41	export const SEASONAL_PROMOS: Promo[] = [
42	  { id: "new-year",       name: "New Year Sale",       label: "New Year Sale",   discountPercent: 30, start: "01-01", end: "01-07" },
43	  { id: "valentines",     name: "Valentine's Sale",    label: "Valentine's Sale", discountPercent: 20, start: "02-08", end: "02-16" },
44	  { id: "spring",         name: "Spring Sale",         label: "Spring Sale",     discountPercent: 25, start: "03-20", end: "04-05" },
45	  { id: "summer",         name: "Summer Sale",         label: "Summer Sale",     discountPercent: 30, start: "06-21", end: "08-10" },
46	  { id: "back-to-school", name: "Back-to-School Sale", label: "Back-to-School",  discountPercent: 25, start: "08-15", end: "09-15" },
47	  { id: "halloween",      name: "Halloween Sale",      label: "Halloween Sale",  discountPercent: 25, start: "10-24", end: "10-31" },
48	  { id: "black-friday",   name: "Black Friday",        label: "Black Friday",    discountPercent: 40, start: "11-24", end: "11-30" },
49	  { id: "cyber-monday",   name: "Cyber Monday",        label: "Cyber Monday",    discountPercent: 45, start: "12-01", end: "12-02" },
50	  { id: "holiday",        name: "Holiday Sale",        label: "Holiday Sale",    discountPercent: 35, start: "12-15", end: "12-31" },
51	];
52	
53	/**
54	 * Always-on modest fallback so there is ALWAYS an active promo between seasons.
55	 * Its real end date is the start of the next seasonal promo (see promoEndsAt) —
56	 * an honest "the Launch Sale runs until the next sale begins".
57	 */
58	export const LAUNCH_SALE: Promo = {
59	  id: "launch",
60	  name: "Launch Sale",
61	  label: "Launch Sale",
62	  discountPercent: 15,
63	  start: "01-01",
64	  end: "12-31",
65	};
66	
67	/** Build a concrete Date for a given year + "MM-DD" (local time). */
68	function dateAt(year: number, mmdd: string, endOfDay: boolean): Date {
69	  const [m, d] = mmdd.split("-").map(Number);
70	  return endOfDay
71	    ? new Date(year, m - 1, d, 23, 59, 59, 999)
72	    : new Date(year, m - 1, d, 0, 0, 0, 0);
73	}
74	
75	/**
76	 * Resolve a promo's window to the concrete [start, end] occurrence around `now`,
77	 * correctly handling a window that wraps the year boundary (e.g. 12-28..01-03).
78	 */
79	function windowBounds(now: Date, promo: Promo): { start: Date; end: Date } {
80	  const y = now.getFullYear();
81	  let start = dateAt(y, promo.start, false);
82	  let end = dateAt(y, promo.end, true);
83	  if (end < start) {
84	    // Wrapping window: pick the occurrence that surrounds `now`.
85	    if (now >= start) end = dateAt(y + 1, promo.end, true); // December side
86	    else start = dateAt(y - 1, promo.start, false); // January side
87	  }
88	  return { start, end };
89	}
90	
91	function inWindow(now: Date, promo: Promo): boolean {
92	  const { start, end } = windowBounds(now, promo);
93	  return now >= start && now <= end;
94	}
95	
96	/** Earliest upcoming seasonal-promo start strictly after `now`. */
97	function nextSeasonalStart(now: Date): Date {
98	  const y = now.getFullYear();
99	  let best: Date | null = null;
100	  for (const p of SEASONAL_PROMOS) {
101	    // Consider this year's and next year's occurrence so year-end wraps around.
102	    for (const yr of [y, y + 1]) {
103	      const s = dateAt(yr, p.start, false);
104	      if (s > now && (!best || s < best)) best = s;
105	    }
106	  }
107	  return best ?? dateAt(y + 1, SEASONAL_PROMOS[0].start, false);
108	}
109	
110	/**
111	 * The active promo for `now`: the first seasonal promo whose window covers it,
112	 * or the always-on Launch Sale fallback. Never returns null — there is always a
113	 * genuine, honest promo running.
114	 */
115	export function currentPromo(now: Date): Promo {
116	  for (const p of SEASONAL_PROMOS) {
117	    if (inWindow(now, p)) return p;
118	  }
119	  return LAUNCH_SALE;
120	}
121	
122	/**
123	 * The genuine first-term price for a regular price under `promo`.
124	 * round(regularCents * (1 - discountPercent/100)). This exact value is what
125	 * checkout charges for the first term — display it verbatim.
126	 */
127	export function promoPriceCents(regularCents: number, promo: Promo): number {
128	  return Math.round(regularCents * (1 - promo.discountPercent / 100));
129	}
130	
131	/**
132	 * The REAL Date the current promo window closes (drives the countdown).
133	 *  - A seasonal promo: the end instant of its active window.
134	 *  - The Launch Sale fallback: genuinely ends when the next seasonal promo
135	 *    begins (the next sale takes over), so the countdown is truthful.
136	 */
137	export function promoEndsAt(now: Date, promo: Promo): Date {
138	  if (promo.id === LAUNCH_SALE.id) return nextSeasonalStart(now);
139	  return windowBounds(now, promo).end;
140	}
