8	 * the wallet immediately — no webhook (and therefore no HTTPS) required. When the
9	 * session carries a direct-pay order intent, the server is provisioned right away
10	 * (once — guarded by the idempotent credit).
11	 */
12	export async function GET(req: NextRequest) {
13	  const base = process.env.APP_URL ?? "";
14	  const sessionId = req.nextUrl.searchParams.get("session_id");
15	  if (!stripeConfigured() || !sessionId) {
16	    return NextResponse.redirect(`${base}/dashboard/billing`);
17	  }
18	  try {
19	    const credited = await creditCheckoutSession(sessionId);
20	    const order = await getCheckoutOrderIntent(sessionId);
21	    if (order) {
22	      // `credited` is true only on the first successful credit for this session,
23	      // so provisioning runs exactly once even if the confirm URL is reloaded.
24	      if (credited) {
25	        const user = await db.user.findUnique({ where: { id: order.userId } });
26	        if (user) {
27	          try {
28	            const serverId = await placeOrder(user, order.intent);
29	            return NextResponse.redirect(`${base}/dashboard/servers/${serverId}`);
30	          } catch {
31	            // Payment captured but provisioning failed — funds are in the wallet.
32	            return NextResponse.redirect(`${base}/dashboard/deploy?paid=1`);
33	          }
34	        }
35	      }
36	      return NextResponse.redirect(`${base}/dashboard/servers`);
37	    }
38	    return NextResponse.redirect(`${base}/dashboard/billing?paid=1`);
39	  } catch {
40	    return NextResponse.redirect(`${base}/dashboard/billing?pending=1`);
41	  }
