11	const GRACE_DAYS = Number(process.env.NXEON_GRACE_DAYS ?? 3);
12	const RENEW_DAYS = 30;
13	const DOMAIN_RENEW_WINDOW_DAYS = 7;
14	/** Days a server stays SUSPENDED (unpaid) before it is permanently terminated. */
15	const TERMINATE_DAYS = Number(process.env.NXEON_TERMINATE_DAYS ?? 10);
16	/** Warn the customer this many days before termination. */
17	const WARN_BEFORE_TERMINATE_DAYS = Number(process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS ?? 2);
18	const DAY = 86400_000;
19	
20	/**
21	 * Subscription sweep, run periodically by the worker:
22	 *  - expired + autoRenew + sufficient balance  -> charge wallet, extend 30 days
23	 *  - expired beyond grace (or autoRenew off)   -> queue SUSPEND with unpaid note
24	 * Free servers (isFree) are never touched.
25	 */
26	export async function billingSweep() {
27	  const now = new Date();
28	
29	  // Renewal warnings: notify once when a paid server is within 3 days of expiry
30	  const soon = new Date(now.getTime() + 3 * 86400_000);
31	  const upcoming = await db.server.findMany({
32	    where: {
33	      isFree: false,
34	      expiresAt: { gt: now, lt: soon },
35	      status: { in: ["RUNNING", "STOPPED"] },
36	    },
37	    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
38	  });
39	  for (const server of upcoming) {
40	    const warnCents = server.gamePlan
41	      ? server.gamePlan.priceCents
42	      : vpsTermPriceCents(server.plan.priceCents, server.termMonths) +
43	        (server.dedicatedIp ? DEDICATED_IP_PRICE_CENTS * server.termMonths : 0);
44	    if (server.autoRenew && server.user.balanceCents >= warnCents) continue;
45	    const already = await db.notification.findFirst({
46	      where: {
47	        userId: server.userId,
48	        title: { contains: server.hostname },
49	        createdAt: { gt: new Date(now.getTime() - 4 * 86400_000) },
50	        AND: { title: { contains: "renews soon" } },
51	      },
52	    });
53	    if (!already) {
54	      await db.notification.create({
55	        data: {
56	          userId: server.userId,
57	          title: `${server.hostname} renews soon — action needed`,
58	          body: server.autoRenew
59	            ? `Renewal is $${(server.plan.priceCents / 100).toFixed(2)} but your balance is $${(server.user.balanceCents / 100).toFixed(2)}. Top up to avoid suspension.`
60	            : `Auto-renew is off. Renew manually before ${server.expiresAt!.toISOString().slice(0, 10)} to avoid suspension.`,
61	          href: `/dashboard/servers/${server.id}`,
62	        },
63	      });
64	    }
65	  }
66	  const due = await db.server.findMany({
67	    where: {
68	      isFree: false,
69	      expiresAt: { lt: now },
70	      status: { in: ["RUNNING", "STOPPED"] },
71	    },
72	    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
73	  });
74	
75	  for (const server of due) {
76	    const graceEnd = new Date(server.expiresAt!.getTime() + GRACE_DAYS * 86400_000);
77	    const renewTerm = vpsTerm(server.termMonths);
78	    const isGame = !!server.gamePlan;
79	    const renewMonths = isGame ? server.gamePlan!.termMonths : renewTerm.months;
80	    const renewCents = isGame
81	      ? server.gamePlan!.priceCents
82	      : vpsTermPriceCents(server.plan.priceCents, renewTerm.months) +
83	        // Bill the IP surcharge only when the server ACTUALLY holds a dedicated IP
84	        // (the DedicatedIp row is the source of truth), not off the intent flag —
85	        // otherwise a NAT-fallback server is charged forever for an IP it never got.
86	        (server.dedicatedIp ? DEDICATED_IP_PRICE_CENTS * renewTerm.months : 0);
