88	    // NOTE: `server.user.balanceCents` came from a snapshot taken before this loop,
89	    // so it is stale as soon as the first renewal in this pass debits the wallet.
90	    // Never gate the charge on it — `debitWallet` re-checks funds atomically, and a
91	    // compare-and-swap on `expiresAt` stops a concurrent renewNow()/second pass from
92	    // charging the same period twice.
93	    let renewed = false;
94	    if (server.autoRenew) {
95	      const base = new Date(Math.max(server.expiresAt!.getTime(), now.getTime()));
96	      const newExpiry = addMonths(base, renewMonths);
97	      try {
98	        await db.$transaction(async (tx) => {
99	          const advanced = await tx.server.updateMany({
100	            where: { id: server.id, expiresAt: server.expiresAt },
101	            data: { expiresAt: newExpiry },
102	          });
103	          if (advanced.count === 0) throw new AlreadyRenewedError();
104	          await debitWallet(tx, server.userId, renewCents);
105	          await tx.walletTransaction.create({
106	            data: {
107	              userId: server.userId,
108	              amountCents: -renewCents,
109	              description: `Renewal: ${isGame ? server.gamePlan!.name : `${server.plan.name} VPS`} (${server.hostname})`,
110	            },
111	          });
112	          // PAID invoice for this renewal period. Inside the CAS-guarded tx, so a
113	          // retried/concurrent sweep hits AlreadyRenewedError and rolls back —
114	          // never producing a second invoice for the same period.
115	          const renewLabel = isGame ? server.gamePlan!.name : `${server.plan.name} VPS`;
116	          await tx.invoice.create({
117	            data: invoiceCreateData({
118	              userId: server.userId,
119	              description: `Renewal: ${renewLabel} (${server.hostname})`,
120	              status: "PAID",
121	              period: { start: server.expiresAt, end: newExpiry },
122	              lineItems: [
123	                { description: `${renewLabel} — ${server.hostname}`, qty: 1, unitCents: renewCents, amountCents: renewCents },
124	              ],
125	            }),
126	          });
127	          await tx.auditLog.create({
128	            data: { userId: server.userId, action: "billing.renewed", detail: server.id },
129	          });
130	        });
131	        renewed = true;
132	        console.log(`[billing] renewed ${server.hostname} until ${newExpiry.toISOString()}`);
133	      } catch (e) {
134	        if (e instanceof InsufficientBalanceError) {
135	          console.log(`[billing] insufficient balance for ${server.hostname} — falling through to grace/suspend`);
136	        } else if (e instanceof AlreadyRenewedError) {
137	          renewed = true; // someone else advanced the period; nothing owed here
138	        } else {
139	          throw e;
140	        }
141	      }
142	    }
143	    if (renewed) {
144	      // nothing further this pass
145	    } else if (now > graceEnd) {
146	      const pending = await db.job.count({
147	        where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
148	      });
149	      if (pending === 0) {
150	        await db.server.update({
151	          where: { id: server.id },
152	          data: { suspendedNote: "unpaid — renew from your billing page to restore access" },
153	        });
154	        await db.job.create({ data: { type: "SUSPEND", serverId: server.id } });
155	        await db.auditLog.create({
156	          data: { userId: server.userId, action: "billing.suspended_unpaid", detail: server.id },
157	        });
158	        await db.notification.create({
159	          data: {
160	            userId: server.userId,
161	            title: `${server.hostname} suspended — payment overdue`,
162	            body: "Pay from the server page to restore access instantly.",
163	            href: `/dashboard/servers/${server.id}`,
164	          },
165	        });
166	        console.log(`[billing] suspending unpaid ${server.hostname}`);
167	      }
168	    }
169	  }
170	
171	  await terminateOverdue(now);
172	
173	  await domainAutoRenewSweep(now);
174	}
