176	/**
177	 * Terminate servers that have been SUSPENDED (unpaid) past the termination window,
178	 * reclaiming disk + dedicated IP. Warns the customer before the final deletion.
179	 * A payment before this point unsuspends the server, so this only ever hits
180	 * genuinely abandoned accounts. Free servers are never terminated.
181	 */
182	async function terminateOverdue(now: Date) {
183	  const suspended = await db.server.findMany({
184	    where: { isFree: false, status: "SUSPENDED", expiresAt: { not: null } },
185	  });
186	  for (const server of suspended) {
187	    const terminateAt = server.expiresAt!.getTime() + (GRACE_DAYS + TERMINATE_DAYS) * DAY;
188	    const warnAt = terminateAt - WARN_BEFORE_TERMINATE_DAYS * DAY;
189	
190	    if (now.getTime() >= terminateAt) {
191	      const pending = await db.job.count({
192	        where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
193	      });
194	      if (pending > 0) continue;
195	      await db.server.update({ where: { id: server.id }, data: { status: "DELETING" } });
196	      await db.job.create({ data: { type: "DELETE", serverId: server.id } });
197	      await db.auditLog.create({
198	        data: { userId: server.userId, action: "billing.terminated_unpaid", detail: server.id },
199	      });
200	      await db.notification.create({
201	        data: {
202	          userId: server.userId,
203	          title: `${server.hostname} was permanently deleted`,
204	          body: "Your server and its data were removed after prolonged non-payment.",
205	        },
206	      });
207	      console.log(`[billing] terminating abandoned ${server.hostname}`);
208	    } else if (now.getTime() >= warnAt) {
209	      const already = await db.notification.findFirst({
210	        where: {
211	          userId: server.userId,
212	          title: { contains: server.hostname },
213	          AND: { title: { contains: "will be deleted" } },
214	          createdAt: { gt: new Date(now.getTime() - 2 * DAY) },
215	        },
216	      });
217	      if (!already) {
218	        await db.notification.create({
219	          data: {
220	            userId: server.userId,
221	            title: `${server.hostname} will be deleted soon`,
222	            body: `This suspended server and all its data will be permanently deleted on ${new Date(terminateAt).toISOString().slice(0, 10)} unless you pay. Restore it now from your billing page.`,
223	            href: `/dashboard/servers/${server.id}`,
224	          },
225	        });
226	      }
227	    }
228	  }
229	}
