231	/**
232	 * Auto-renew domains expiring within 7 days when the owner opted in and has
233	 * the funds. Charges the wallet, extends expiry +365d and notifies the owner.
234	 * Failures (registrar error, misconfig) notify the owner to renew manually and
235	 * never charge the wallet.
236	 */
237	async function domainAutoRenewSweep(now: Date) {
238	  if (!registrarConfigured()) return; // registrar not configured — skip silently
239	
240	  const cutoff = new Date(now.getTime() + DOMAIN_RENEW_WINDOW_DAYS * 86400_000);
241	  const domains = await db.domain.findMany({
242	    where: {
243	      autoRenew: true,
244	      status: "ACTIVE",
245	      expiresAt: { not: null, lt: cutoff },
246	    },
247	    include: { user: true },
248	  });
249	
250	  for (const domain of domains) {
251	    if (!domain.expiresAt) continue;
252	    const dTerm = domainTerm(domain.termYears);
253	    const dRenewCents = domainTermPriceCents(domain.priceCents, dTerm.years); // retail (customer)
254	    const dRegistrarCost = (domain.costCents || domain.priceCents) * dTerm.years; // cost (registrar)
255	    if (domain.user.balanceCents < dRenewCents) {
256	      const already = await db.notification.findFirst({
257	        where: {
258	          userId: domain.userId,
259	          title: { contains: domain.name },
260	          AND: { title: { contains: "auto-renew failed" } },
261	          createdAt: { gt: new Date(now.getTime() - 3 * 86400_000) },
262	        },
263	      });
264	      if (!already) {
265	        await db.notification.create({
266	          data: {
267	            userId: domain.userId,
268	            title: `${domain.name} auto-renew failed — top up to renew`,
269	            body: `Renewal is $${(dRenewCents / 100).toFixed(2)} (${dTerm.label}) but your balance is $${(domain.user.balanceCents / 100).toFixed(2)}. Top up and renew manually before ${domain.expiresAt.toISOString().slice(0, 10)}.`,
270	            href: `/dashboard/domains`,
271	          },
272	        });
273	      }
274	      continue;
275	    }
276	
277	    try {
278	      await renewDomain(domain.name, dTerm.years, dRegistrarCost);
279	    } catch (e) {
280	      console.error(`[billing] domain auto-renew failed for ${domain.name}`, e);
281	      await db.notification.create({
282	        data: {
283	          userId: domain.userId,
284	          title: `${domain.name} auto-renew failed — please renew manually`,
285	          body: `We couldn't renew ${domain.name} automatically: ${String((e as any)?.message ?? e).slice(0, 200)}. Renew it manually from your domains page.`,
286	          href: `/dashboard/domains`,
287	        },
288	      });
289	      continue;
290	    }
291	
292	    const newExpiry = new Date(domain.expiresAt.getTime() + dTerm.years * 365 * 86400_000);
293	    // The registrar renewal already succeeded above, so the cost is committed.
294	    // Charge with the guarded debit (the loop's snapshot balance is stale), and
295	    // CAS the expiry so a concurrent manual renew can't be charged twice. If the
296	    // wallet can't cover it we must STILL record the renewal we paid for — flag it
297	    // as uncharged for ops rather than silently eating it or renewing twice later.
298	    try {
299	      await db.$transaction(async (tx) => {
300	        const advanced = await tx.domain.updateMany({
301	          where: { id: domain.id, expiresAt: domain.expiresAt },
302	          data: { expiresAt: newExpiry },
303	        });
304	        if (advanced.count === 0) throw new AlreadyRenewedError();
305	        await debitWallet(tx, domain.userId, dRenewCents);
306	        await tx.walletTransaction.create({
307	          data: {
308	            userId: domain.userId,
309	            amountCents: -dRenewCents,
310	            description: `Domain auto-renewal: ${domain.name} (${dTerm.label})`,
311	          },
312	        });
313	        // PAID invoice on the successfully-charged path only (the uncharged
314	        // InsufficientBalance branch below deliberately makes no invoice). Inside
315	        // the CAS-guarded tx, so a repeated sweep rolls it back with the debit.
316	        await tx.invoice.create({
317	          data: invoiceCreateData({
318	            userId: domain.userId,
319	            description: `Domain auto-renewal: ${domain.name} (${dTerm.label})`,
320	            status: "PAID",
321	            period: { start: domain.expiresAt, end: newExpiry },
322	            lineItems: [
323	              { description: `Domain renewal — ${domain.name} (${dTerm.label})`, qty: 1, unitCents: dRenewCents, amountCents: dRenewCents },
324	            ],
325	          }),
326	        });
327	        await tx.auditLog.create({
328	          data: { userId: domain.userId, action: "domain.auto_renewed", detail: domain.name },
329	        });
330	      });
331	    } catch (e) {
332	      if (e instanceof AlreadyRenewedError) {
333	        continue; // someone already advanced this period
334	      }
335	      if (e instanceof InsufficientBalanceError) {
336	        await db.domain.update({ where: { id: domain.id }, data: { expiresAt: newExpiry } });
337	        await db.auditLog.create({
338	          data: {
339	            userId: domain.userId,
340	            action: "domain.renew.uncharged",
341	            detail: `${domain.name}: renewed at registrar but wallet could not be charged ${dRenewCents}c — collect manually`,
342	          },
343	        });
344	        console.error(`[billing] UNCHARGED domain renewal for ${domain.name} (insufficient balance)`);
345	        continue;
346	      }
347	      throw e;
348	    }
349	    await db.notification.create({
350	      data: {
351	        userId: domain.userId,
352	        title: `${domain.name} renewed automatically`,
353	        body: `Charged $${(domain.priceCents / 100).toFixed(2)}. New expiry: ${newExpiry.toISOString().slice(0, 10)}.`,
354	        href: `/dashboard/domains`,
355	      },
356	    });
357	    console.log(`[billing] auto-renewed domain ${domain.name} until ${newExpiry.toISOString()}`);
358	  }
359	}
