236	/** Renew / warn / suspend every ACTIVE subscription that is past its expiry. */
237	async function emailDueSweep(now: Date) {
238	  const due = await db.emailSubscription.findMany({
239	    where: { status: "ACTIVE", expiresAt: { not: null, lt: now } },
240	    include: { emailPlan: true, user: true },
241	  });
242	
243	  for (const sub of due) {
244	    await step(`email renewal ${sub.id}`, async () => {
245	      if (!sub.expiresAt) return;
246	      const priceCents = emailRenewalCents(sub.emailPlan);
247	      const action = renewalDecision({
248	        expiresAt: sub.expiresAt,
249	        now,
250	        autoRenew: sub.autoRenew,
251	        balanceCents: sub.user.balanceCents,
252	        priceCents,
253	      });
254	
255	      if (action === "renew") {
256	        const newExpiry = nextExpiry(sub.expiresAt, now, emailRenewalMonths(sub.emailPlan));
257	        const renewed = await chargeEmailRenewal(sub, sub.emailPlan.name, priceCents, newExpiry);
258	        if (!renewed) return;
259	        await notify(
260	          sub.userId,
261	          `${sub.domainName} email renewed`,
262	          `Charged ${money(priceCents)} for ${sub.emailPlan.name}. Next renewal ${ymd(newExpiry)}.`,
263	          EMAIL_HREF
264	        );
265	        console.log(`${LOG} renewed email ${sub.domainName} until ${newExpiry.toISOString()}`);
266	        return;
267	      }
268	
269	      if (action === "enforce") {
270	        await suspendEmail(sub, priceCents);
271	        return;
272	      }
273	
274	      // Still inside the grace window — keep it delivering, nag once.
275	      await notifyOnce(
276	        now,
277	        sub.userId,
278	        sub.domainName,
279	        "email renewal failed",
280	        `${sub.domainName} email renewal failed — top up to keep it active`,
281	        sub.autoRenew
282	          ? `We couldn't charge ${money(priceCents)} (balance ${money(sub.user.balanceCents)}). Mail keeps flowing until ${ymd(graceEndsAt(sub.expiresAt, PRODUCT_GRACE_DAYS))}, then the subscription is suspended. Your mailboxes are not deleted.`
283	          : `Auto-renew is off and this subscription expired. Renew before ${ymd(graceEndsAt(sub.expiresAt, PRODUCT_GRACE_DAYS))} to avoid suspension. Your mailboxes are not deleted.`,
284	        EMAIL_HREF
285	      );
286	    });
287	  }
288	}
