1	/**
2	 * Pricing + renewal-period math for the recurring add-on products
3	 * (business email subscriptions and block-storage volumes).
4	 *
5	 * Deliberately PURE: no `db`, no I/O, no side effects — everything here is a
6	 * plain function over plain values so the renewal policy can be unit-tested
7	 * without a database. The worker sweep (`worker/product-renewals.ts`) owns all
8	 * the reads/writes and asks this module *what* should happen.
9	 *
10	 * Policy shape mirrors `worker/billing.ts` (VPS/domains) so customers see one
11	 * consistent billing behaviour across every product:
12	 *   warn before expiry -> expire -> grace period -> enforce (suspend / detach)
13	 */
14	
15	import { addMonths } from "./billing-terms";
16	
17	export const DAY_MS = 86_400_000;
18	
19	/** Read a positive integer from the environment, falling back on a default. */
20	export function envInt(name: string, fallback: number): number {
21	  const raw = process.env[name];
22	  const n = Number(raw);
23	  return raw !== undefined && Number.isFinite(n) && n >= 0 ? n : fallback;
24	}
25	
26	/**
27	 * Days after expiry during which the product keeps working while we retry the
28	 * charge and nag the customer. Shares NXEON_GRACE_DAYS with worker/billing.ts
29	 * so every product on the account expires on the same schedule.
30	 */
31	export const PRODUCT_GRACE_DAYS = envInt("NXEON_GRACE_DAYS", 3);
32	
33	/** How many days before expiry we send the "renews soon" heads-up. */
34	export const PRODUCT_WARN_DAYS = envInt("NXEON_PRODUCT_WARN_DAYS", 3);
35	
36	/**
37	 * Days after the grace window before an unpaid, detached volume is considered
38	 * abandoned and may be reclaimed by staff. Nothing in this codebase deletes
39	 * customer data automatically — this only drives the wording of the warning so
40	 * the customer knows the disk will not sit there unpaid forever.
41	 */
42	export const PRODUCT_RECLAIM_DAYS = envInt("NXEON_TERMINATE_DAYS", 10);
43	
44	/** Notification dedupe window (matches the 4-day window used by billing.ts). */
45	export const NOTIFY_DEDUPE_DAYS = envInt("NXEON_PRODUCT_NOTIFY_DEDUPE_DAYS", 4);
46	
47	/** Volumes are priced per month and always renew monthly. */
48	export const VOLUME_TERM_MONTHS = 1;
49	
50	/** "$12.34" — the money format used across notifications and wallet lines. */
51	export function money(cents: number): string {
52	  return `$${(cents / 100).toFixed(2)}`;
53	}
54	
55	/** Date as "YYYY-MM-DD" for human-readable deadlines in notifications. */
56	export function ymd(d: Date): string {
57	  return d.toISOString().slice(0, 10);
58	}
59	
60	/** Amount charged to renew an email subscription for one plan term. */
61	export function emailRenewalCents(plan: { priceCents: number }): number {
62	  return Math.max(0, Math.round(plan.priceCents));
63	}
64	
65	/** Plan term in whole months, clamped to >= 1 so a bad row can't stall renewal. */
66	export function emailRenewalMonths(plan: { termMonths?: number | null }): number {
67	  const m = Math.round(Number(plan.termMonths ?? 1));
68	  return Number.isFinite(m) && m >= 1 ? m : 1;
69	}
70	
71	/** Amount charged to renew a volume for one month. */
72	export function volumeRenewalCents(volume: { priceCents: number }): number {
73	  return Math.max(0, Math.round(volume.priceCents));
74	}
75	
76	/**
77	 * The expiry a renewal should advance to.
78	 *
79	 * The base is `max(currentExpiry, now)`, so an item that has been expired for
80	 * months is brought forward to one full term from *today* with a single charge
81	 * rather than being back-billed for every missed period. This also guarantees
82	 * the new expiry is always strictly in the future, which is what makes the
83	 * sweep idempotent (the "due" query only selects `expiresAt < now`).
84	 */
85	export function nextExpiry(
86	  currentExpiry: Date | null | undefined,
87	  now: Date,
88	  months: number
89	): Date {
90	  const base = new Date(
91	    Math.max(currentExpiry ? currentExpiry.getTime() : now.getTime(), now.getTime())
92	  );
93	  return addMonths(base, Math.max(1, Math.round(months)));
94	}
95	
96	/** Instant the grace period ends for an item that expired at `expiresAt`. */
97	export function graceEndsAt(expiresAt: Date, graceDays: number = PRODUCT_GRACE_DAYS): Date {
98	  return new Date(expiresAt.getTime() + graceDays * DAY_MS);
99	}
100	
101	/** True once the grace period after `expiresAt` has fully elapsed. */
102	export function isPastGrace(
103	  expiresAt: Date,
104	  now: Date,
105	  graceDays: number = PRODUCT_GRACE_DAYS
106	): boolean {
107	  return now.getTime() > graceEndsAt(expiresAt, graceDays).getTime();
108	}
109	
110	/** Date after which an unpaid volume may be reclaimed (messaging only). */
111	export function reclaimAt(
112	  expiresAt: Date,
113	  graceDays: number = PRODUCT_GRACE_DAYS,
114	  reclaimDays: number = PRODUCT_RECLAIM_DAYS
115	): Date {
116	  return new Date(expiresAt.getTime() + (graceDays + reclaimDays) * DAY_MS);
117	}
118	
119	/** Lower bound for "have we already sent this notification recently?" lookups. */
120	export function dedupeSince(now: Date, days: number = NOTIFY_DEDUPE_DAYS): Date {
121	  return new Date(now.getTime() - days * DAY_MS);
122	}
123	
124	/** True when the item has passed its paid-through date and owes a renewal. */
125	export function isDueForRenewal(expiresAt: Date | null | undefined, now: Date): boolean {
126	  return !!expiresAt && expiresAt.getTime() < now.getTime();
127	}
128	
129	/** True when the item expires inside the pre-expiry warning window. */
130	export function isRenewingSoon(
131	  expiresAt: Date | null | undefined,
132	  now: Date,
133	  warnDays: number = PRODUCT_WARN_DAYS
134	): boolean {
135	  if (!expiresAt) return false;
136	  const t = expiresAt.getTime();
137	  return t > now.getTime() && t < now.getTime() + warnDays * DAY_MS;
138	}
139	
140	/** Whether the wallet covers a renewal (free items always "afford" themselves). */
141	export function canAfford(balanceCents: number, priceCents: number): boolean {
142	  return priceCents <= 0 || balanceCents >= priceCents;
143	}
144	
145	/**
146	 * What the sweep should do with an item that is past its expiry date.
147	 *  - `renew`   charge the wallet and push `expiresAt` forward
148	 *  - `grace`   still inside the grace window: leave it running, nag the owner
149	 *  - `enforce` grace elapsed and unpaid: suspend (email) / detach (volume)
150	 */
151	export type RenewalAction = "renew" | "grace" | "enforce";
152	
153	export function renewalDecision(opts: {
154	  expiresAt: Date;
155	  now: Date;
156	  autoRenew: boolean;
157	  balanceCents: number;
158	  priceCents: number;
159	  graceDays?: number;
160	}): RenewalAction {
161	  const { expiresAt, now, autoRenew, balanceCents, priceCents } = opts;
162	  if (autoRenew && canAfford(balanceCents, priceCents)) return "renew";
163	  if (isPastGrace(expiresAt, now, opts.graceDays)) return "enforce";
164	  return "grace";
165	}
166	
167	/**
168	 * Whether a pre-expiry warning is warranted: only bother the customer when the
169	 * renewal would actually fail today (auto-renew off, or wallet too low).
170	 */
171	export function needsUpcomingWarning(opts: {
172	  autoRenew: boolean;
173	  balanceCents: number;
174	  priceCents: number;
175	}): boolean {
176	  return !(opts.autoRenew && canAfford(opts.balanceCents, opts.priceCents));
177	}
