108	function esc(s: unknown): string {
109	  return String(s ?? "")
110	    .replace(/&/g, "&amp;")
111	    .replace(/</g, "&lt;")
112	    .replace(/>/g, "&gt;")
113	    .replace(/"/g, "&quot;");
114	}
