1	"use server";
2	
3	import { z } from "zod";
4	import { revalidatePath } from "next/cache";
5	import type { Coupon } from "@prisma/client";
6	import { db } from "./db";
7	import { requireUser, requireAdmin } from "./auth";
8	import { getSettingBool, getSettingInt } from "./settings";
9	import {
10	  describeCoupon,
11	  referralRewardCents,
12	  signupFreeCreditCents,
13	  type CouponApplyResult,
14	} from "./growth";
15	
16	// ---------- Coupons ----------
17	
18	/**
19	 * Compute the extra wallet credit a coupon grants for a top-up of `baseCents`.
20	 * PERCENT -> baseCents * value%; FIXED_CENTS / CREDIT_CENTS -> flat `value` cents.
21	 */
22	function couponBonusForTopup(coupon: Coupon, baseCents: number): number {
23	  switch (coupon.kind) {
24	    case "PERCENT":
25	      return Math.round((baseCents * coupon.value) / 100);
26	    case "FIXED_CENTS":
27	    case "CREDIT_CENTS":
28	      return coupon.value;
29	    default:
30	      return 0;
31	  }
32	}
33	
34	/**
35	 * Validate a promo code for the CURRENT user against a top-up of `baseCents` and
36	 * return the bonus that would be credited. Read-only: it never mutates state,
37	 * so it is safe to call both for the live preview (CouponField) and again inside
38	 * `topUp` to compute the real bonus. Enforces active / expiry / scope /
39	 * minAmount / maxRedemptions / firstTimeOnly / one-per-user rules.
40	 */
41	export async function applyCouponToTopup(
42	  code: string,
43	  baseCents: number
44	): Promise<CouponApplyResult> {
45	  const user = await requireUser();
46	  // Global kill-switch: when coupons are disabled no code may be redeemed.
47	  // Checked here so both the live preview and the real `topUp` apply are covered.
48	  if (!(await getSettingBool("coupons_enabled", true))) {
49	    return { ok: false, error: "Promo codes are currently disabled." };
50	  }
51	  const normalized = String(code ?? "").trim().toUpperCase();
52	  if (!normalized) return { ok: false, error: "Enter a promo code." };
53	
54	  const coupon = await db.coupon.findUnique({ where: { code: normalized } });
55	  if (!coupon || !coupon.active) return { ok: false, error: "That code isn’t valid." };
56	  if (coupon.scope === "ORDER") {
57	    return { ok: false, error: "This code only applies to server orders." };
58	  }
59	  if (coupon.expiresAt && coupon.expiresAt.getTime() < Date.now()) {
60	    return { ok: false, error: "This code has expired." };
61	  }
62	  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
63	    return { ok: false, error: "This code has reached its redemption limit." };
64	  }
65	  if (coupon.minAmountCents !== null && baseCents < coupon.minAmountCents) {
66	    return {
67	      ok: false,
68	      error: `Add at least $${(coupon.minAmountCents / 100).toFixed(2)} to use this code.`,
69	    };
70	  }
71	
72	  // One redemption per user (mirrors the @@unique([couponId,userId]) constraint).
73	  const already = await db.couponRedemption.findUnique({
74	    where: { couponId_userId: { couponId: coupon.id, userId: user.id } },
75	  });
76	  if (already) return { ok: false, error: "You’ve already used this code." };
77	
78	  if (coupon.firstTimeOnly) {
79	    // "First-time" = the user has never received a positive wallet credit before.
80	    const priorCredits = await db.walletTransaction.count({
81	      where: { userId: user.id, amountCents: { gt: 0 } },
82	    });
83	    if (priorCredits > 0) {
84	      return { ok: false, error: "This code is for first-time customers only." };
85	    }
86	  }
87	
88	  const bonusCents = Math.max(0, couponBonusForTopup(coupon, baseCents));
89	  return {
90	    ok: true,
91	    couponId: coupon.id,
92	    code: coupon.code,
93	    bonusCents,
94	    label: describeCoupon(coupon),
95	  };
96	}
97	
98	// ---------- Admin: coupon management ----------
99	
100	const couponSchema = z.object({
101	  code: z
102	    .string()
103	    .trim()
104	    .min(3)
105	    .max(32)
106	    .regex(/^[A-Za-z0-9_-]+$/, "Code: letters, digits, dashes/underscores only."),
107	  kind: z.enum(["PERCENT", "FIXED_CENTS", "CREDIT_CENTS"]),
108	  scope: z.enum(["ANY", "TOPUP", "ORDER"]),
109	  value: z.coerce.number().int().min(1).max(1_000_000),
110	  firstTimeOnly: z.coerce.boolean(),
111	  minAmountCents: z.coerce.number().int().min(0).max(10_000_000).optional(),
112	  maxRedemptions: z.coerce.number().int().min(1).max(1_000_000).optional(),
113	  expiresAt: z.string().optional(),
114	  note: z.string().max(200).optional(),
115	});
116	
117	export async function adminCreateCoupon(
118	  prev: any,
119	  formData: FormData
120	): Promise<{ error?: string; ok?: boolean }> {
121	  const admin = await requireAdmin();
122	  const rawExpires = String(formData.get("expiresAt") ?? "").trim();
123	  const rawMin = String(formData.get("minAmountCents") ?? "").trim();
124	  const rawMax = String(formData.get("maxRedemptions") ?? "").trim();
125	  const parsed = couponSchema.safeParse({
126	    code: formData.get("code"),
127	    kind: formData.get("kind"),
128	    scope: formData.get("scope"),
129	    value: formData.get("value"),
130	    firstTimeOnly: formData.get("firstTimeOnly") === "on",
131	    minAmountCents: rawMin === "" ? undefined : rawMin,
132	    maxRedemptions: rawMax === "" ? undefined : rawMax,
133	    expiresAt: rawExpires === "" ? undefined : rawExpires,
134	    note: formData.get("note") || undefined,
135	  });
136	  if (!parsed.success) {
137	    return { error: parsed.error.issues[0]?.message ?? "Invalid coupon." };
138	  }
139	  const data = parsed.data;
140	  if (data.kind === "PERCENT" && data.value > 100) {
141	    return { error: "Percent value must be between 1 and 100." };
142	  }
143	  const code = data.code.toUpperCase();
144	
145	  const existing = await db.coupon.findUnique({ where: { code } });
146	  if (existing) return { error: "A coupon with that code already exists." };
147	
148	  let expiresAt: Date | null = null;
149	  if (data.expiresAt) {
150	    const d = new Date(data.expiresAt);
151	    if (Number.isNaN(d.getTime())) return { error: "Invalid expiry date." };
152	    expiresAt = d;
153	  }
154	
155	  await db.coupon.create({
156	    data: {
157	      code,
158	      kind: data.kind,
159	      scope: data.scope,
160	      value: data.value,
161	      firstTimeOnly: data.firstTimeOnly,
162	      minAmountCents: data.minAmountCents ?? null,
163	      maxRedemptions: data.maxRedemptions ?? null,
164	      expiresAt,
165	      note: data.note ?? null,
166	    },
167	  });
168	  await db.auditLog.create({
169	    data: { userId: admin.id, action: "admin.coupon_create", detail: code },
170	  });
171	  revalidatePath("/admin/coupons");
172	  return { ok: true };
173	}
174	
175	export async function adminToggleCoupon(id: string): Promise<void> {
176	  const admin = await requireAdmin();
177	  const coupon = await db.coupon.findUnique({ where: { id } });
178	  if (!coupon) return;
179	  await db.coupon.update({ where: { id }, data: { active: !coupon.active } });
180	  await db.auditLog.create({
181	    data: {
182	      userId: admin.id,
183	      action: "admin.coupon_toggle",
184	      detail: `${coupon.code} -> ${!coupon.active ? "active" : "inactive"}`,
185	    },
186	  });
