514	export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
515	  const { user, server } = await ownedServer(serverId);
516	  if (server.isFree || !server.expiresAt) return;
517	  const plan = await db.plan.findUnique({ where: { id: server.planId } });
518	  if (!plan) return;
519	  const term = vpsTerm(server.termMonths);
520	  const renewCents =
521	    vpsTermPriceCents(plan.priceCents, term.months) +
522	    (server.wantsDedicatedIp ? DEDICATED_IP_PRICE_CENTS * term.months : 0);
523	  const owner = await db.user.findUnique({ where: { id: server.userId } });
524	  if (!owner || owner.balanceCents < renewCents) {
525	    return { error: "Insufficient balance — top up your wallet first." };
526	  }
527	
528	  // `E` is the expiry we read OUTSIDE the transaction. We advance it with a
529	  // compare-and-swap on that exact value so two concurrent "Renew now" clicks
530	  // can't both read E, both debit, and both write E+term (double-charge, one
531	  // term granted). Only the CAS that matches E wins; the loser is a no-op.
532	  const E = server.expiresAt;
533	  const base = new Date(Math.max(E.getTime(), Date.now()));
534	  const newExpiry = addMonths(base, term.months);
535	  try {
536	    await db.$transaction(async (tx) => {
537	      // Compare-and-swap the expiry first; if it no longer equals E another
538	      // renewal already advanced it — bail without charging (tx rolls back).
539	      const adv = await tx.server.updateMany({
540	        where: { id: serverId, expiresAt: E },
541	        data: { expiresAt: newExpiry, suspendedNote: null },
542	      });
543	      if (adv.count === 0) throw new AlreadyRenewedError();
544	      // Atomic guarded debit: a concurrent spend can't drive the wallet negative.
545	      await debitWallet(tx, server.userId, renewCents);
546	      await tx.walletTransaction.create({
547	        data: {
548	          userId: server.userId,
549	          amountCents: -renewCents,
550	          description: `Renewal: ${plan.name} VPS (${server.hostname}) — ${term.label}`,
551	        },
552	      });
553	      // PAID invoice inside the same CAS-guarded tx: a losing concurrent "Renew
554	      // now" throws AlreadyRenewedError and rolls back, so no duplicate invoice.
555	      await tx.invoice.create({
556	        data: invoiceCreateData({
557	          userId: server.userId,
558	          description: `Renewal: ${plan.name} VPS (${server.hostname}) — ${term.label}`,
559	          status: "PAID",
560	          period: { start: E, end: newExpiry },
561	          lineItems: [
562	            { description: `${plan.name} VPS (${server.hostname}) — ${term.label}`, qty: 1, unitCents: renewCents, amountCents: renewCents },
563	          ],
564	        }),
565	      });
566	    });
567	  } catch (e) {
568	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
569	    if (e instanceof AlreadyRenewedError) return { error: "This server was just renewed — refresh to see the new expiry." };
570	    throw e;
571	  }
572	  await audit(user.id, "server.renew_now", serverId);
573	
574	  // Unpaid-suspended server springs back to life once paid
575	  if (server.status === "SUSPENDED") {
576	    const pending = await db.job.count({
