10	/** Alphabet for generated gift codes — no ambiguous chars (0/O, 1/I). */
11	const ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
12	
13	function randomSegment(len: number): string {
14	  let s = "";
15	  for (let i = 0; i < len; i++) s += ALPHABET[randomInt(ALPHABET.length)];
16	  return s;
17	}
18	
19	/** Generate a code like `NXEON-XXXX-XXXX`. */
20	function generateGiftCode(): string {
21	  return `NXEON-${randomSegment(4)}-${randomSegment(4)}`;
22	}
23	
24	/** Allocate a code that is unique in the DB (retry on the rare clash). */
25	async function uniqueGiftCode(): Promise<string> {
26	  for (let i = 0; i < 8; i++) {
27	    const code = generateGiftCode();
28	    const clash = await db.giftCode.findUnique({ where: { code } });
29	    if (!clash) return code;
30	  }
31	  // Extremely unlikely; add a third segment for extra entropy.
32	  return `${generateGiftCode()}-${randomSegment(4)}`;
33	}
