3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { requireArea } from "./rbac";
7	import { debitWallet, InsufficientBalanceError } from "./wallet";
8	import {
9	  MIN_PAYOUT_CENTS,
10	  PAYOUT_STATUSES,
11	  REFERRAL_EARNING_DESCRIPTION,
12	  type PayoutStatus,
13	} from "./affiliate";
14	
15	/** Local sentinel: requested payout exceeds the caller's cashable affiliate balance. */
16	class PayoutExceedsAvailableError extends Error {
17	  availableCents: number;
18	  constructor(availableCents: number) {
19	    super("PAYOUT_EXCEEDS_AVAILABLE");
20	    this.name = "PayoutExceedsAvailableError";
21	    this.availableCents = availableCents;
22	  }
23	}
24	
25	// ---------- Customer: request a payout ----------
26	
27	/**
28	 * Request an affiliate payout for `amountCents`. Model: referral rewards already
29	 * live in the wallet, so a payout CONVERTS wallet credit into a cash-out request —
30	 * it DEBITS the wallet now and records a PENDING AffiliatePayout (admin later marks
31	 * PAID; a DECLINE credits the wallet back). Guards:
32	 *  - integer cents ≥ MIN_PAYOUT_CENTS ($25)
33	 *  - amount ≤ the caller's cashable affiliate balance (unclaimed referral
34	 *    commission, capped by the actual wallet balance), re-read INSIDE the
35	 *    transaction so two concurrent requests can't both pass a stale check.
36	 *  - the wallet debit is an atomic guarded updateMany, so even a race can never
37	 *    drive the balance negative — the second request fails cleanly.
38	 */
39	export async function requestAffiliatePayout(
40	  amountCents: number
41	): Promise<{ ok?: boolean; error?: string }> {
42	  const user = await requireUser();
43	
44	  const cents = Math.round(Number(amountCents));
45	  if (!Number.isFinite(cents) || cents <= 0) {
46	    return { error: "Enter a valid amount." };
47	  }
48	  if (cents < MIN_PAYOUT_CENTS) {
49	    return { error: `Minimum payout is $${(MIN_PAYOUT_CENTS / 100).toFixed(2)}.` };
50	  }
51	
52	  try {
53	    await db.$transaction(async (tx) => {
54	      // Re-read all state inside the tx to serialize concurrent requests.
55	      const [account, earnedAgg, payouts] = await Promise.all([
56	        tx.user.findUnique({ where: { id: user.id }, select: { balanceCents: true } }),
57	        tx.walletTransaction.aggregate({
58	          _sum: { amountCents: true },
59	          where: { userId: user.id, description: REFERRAL_EARNING_DESCRIPTION },
60	        }),
61	        tx.affiliatePayout.findMany({
62	          where: { userId: user.id, status: { not: "DECLINED" } },
63	          select: { amountCents: true },
64	        }),
65	      ]);
66	      const walletBalanceCents = account?.balanceCents ?? 0;
67	      const totalEarnedCents = earnedAgg._sum.amountCents ?? 0;
68	      const claimedCents = payouts.reduce((s, p) => s + p.amountCents, 0);
69	      const availableCents = Math.max(
70	        0,
71	        Math.min(walletBalanceCents, totalEarnedCents - claimedCents)
72	      );
73	      if (cents > availableCents) throw new PayoutExceedsAvailableError(availableCents);
74	
75	      // Atomic guarded debit — hard-stops any residual race from overdrawing.
76	      await debitWallet(tx, user.id, cents);
77	      await tx.walletTransaction.create({
78	        data: {
79	          userId: user.id,
80	          amountCents: -cents,
81	          description: "Affiliate payout request (wallet cash-out)",
82	        },
83	      });
84	      await tx.affiliatePayout.create({
85	        data: { userId: user.id, amountCents: cents, status: "PENDING" },
86	      });
87	      await tx.auditLog.create({
88	        data: {
89	          userId: user.id,
90	          action: "affiliate.payout_request",
91	          detail: `$${(cents / 100).toFixed(2)}`,
92	        },
93	      });
94	    });
95	  } catch (e) {
96	    if (e instanceof PayoutExceedsAvailableError) {
97	      return { error: `You only have $${(e.availableCents / 100).toFixed(2)} available to withdraw.` };
98	    }
99	    if (e instanceof InsufficientBalanceError) {
100	      return { error: "Insufficient wallet balance for this payout." };
101	    }
102	    throw e;
103	  }
104	
105	  revalidatePath("/dashboard/affiliate");
106	  return { ok: true };
107	}
108	
109	// ---------- Admin: update a payout's status ----------
110	
111	const ALLOWED: readonly PayoutStatus[] = PAYOUT_STATUSES;
112	
113	/**
114	 * Move a payout request to APPROVED / PAID / DECLINED. Money already left the
115	 * wallet when the request was created, so:
116	 *   - PAID     : just stamp `paidAt` (no wallet change — cash was already reserved).
117	 *   - DECLINED : credit the reserved amount back to the wallet (cash-out cancelled).
118	 *   - reactivating a DECLINED payout (back to PENDING/APPROVED/PAID): re-debit it,
119	 *     guarded, so a declined-then-reinstated payout can't be double-spent.
120	 * Billing-area gated. The status change + wallet move are one transaction.
121	 */
122	export async function adminUpdatePayout(
123	  id: string,
124	  status: string
125	): Promise<{ ok?: boolean; error?: string }> {
126	  const admin = await requireArea("billing");
127	
128	  if (!ALLOWED.includes(status as PayoutStatus)) {
129	    return { error: "Invalid status." };
130	  }
131	  const payout = await db.affiliatePayout.findUnique({ where: { id } });
132	  if (!payout) return { error: "Payout not found." };
133	
134	  const wasDeclined = payout.status === "DECLINED";
135	  const willDecline = status === "DECLINED";
136	
137	  try {
138	    await db.$transaction(async (tx) => {
139	      await tx.affiliatePayout.update({
140	        where: { id },
141	        data: {
142	          status,
143	          paidAt: status === "PAID" ? new Date() : null,
144	        },
145	      });
146	      if (willDecline && !wasDeclined) {
147	        // Cancel the cash-out: return the reserved funds to the wallet.
148	        await tx.user.update({
149	          where: { id: payout.userId },
150	          data: { balanceCents: { increment: payout.amountCents } },
151	        });
152	        await tx.walletTransaction.create({
153	          data: {
154	            userId: payout.userId,
155	            amountCents: payout.amountCents,
156	            description: "Affiliate payout declined (funds returned)",
157	          },
158	        });
159	      } else if (!willDecline && wasDeclined) {
160	        // Reinstating a previously-declined payout: re-reserve the funds (guarded).
161	        await debitWallet(tx, payout.userId, payout.amountCents);
162	        await tx.walletTransaction.create({
163	          data: {
164	            userId: payout.userId,
165	            amountCents: -payout.amountCents,
166	            description: "Affiliate payout reinstated (wallet cash-out)",
167	          },
168	        });
169	      }
170	    });
171	  } catch (e) {
172	    if (e instanceof InsufficientBalanceError) {
173	      return { error: "Customer's wallet no longer covers this payout — cannot reinstate." };
174	    }
175	    throw e;
176	  }
177	
178	  await db.auditLog.create({
179	    data: {
180	      userId: admin.id,
181	      action: "affiliate.payout_update",
182	      detail: `${payout.id} → ${status} ($${(payout.amountCents / 100).toFixed(2)})`,
183	    },
184	  });
185	
186	  revalidatePath("/admin/affiliate");
187	  return { ok: true };
188	}
