8	/**
9	 * Sandbox-only instant wallet top-up (no Stripe). Credits play money so the full
10	 * ordering/billing flow can be exercised on staging without moving real money.
11	 * Completely inert unless NXEON_SANDBOX=1 — returns an error in production.
12	 */
13	export async function sandboxTopUp(cents: number): Promise<{ error?: string; ok?: boolean }> {
14	  if (!SANDBOX) return { error: "Sandbox top-up is not available here." };
15	  const user = await requireUser();
16	  const amount = Math.min(Math.max(Math.round(cents || 0), 100), 100_000); // $1–$1000
17	  await db.$transaction([
18	    db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: amount } } }),
19	    db.walletTransaction.create({
20	      data: { userId: user.id, amountCents: amount, description: "Sandbox credit (test funds)" },
21	    }),
22	  ]);
23	  revalidatePath("/dashboard/billing");
24	  return { ok: true };
25	}
