1	/**
2	 * Sandbox mode — the staging environment runs as a complete sandbox: the full
3	 * app works end to end (ordering, billing with play-money wallet debits, email
4	 * setup, server lifecycle), but NOTHING touches the outside world:
5	 *   - no real VMs are cloned/started on Proxmox (jobs are simulated)
6	 *   - no failover IPs are ordered from OVH (synthetic IPs are handed out)
7	 *   - no real money moves through Stripe (test keys + an instant-credit bypass)
8	 *
9	 * Gated entirely by the NXEON_SANDBOX env var, which is set ONLY in the staging
10	 * .env. In production the var is unset, so every check below is false and the
11	 * real integrations run exactly as before. This module is a plain (non-"use
12	 * server") module so both the app and the worker daemon can import it.
13	 */
14	export const SANDBOX = process.env.NXEON_SANDBOX === "1";
15	
16	/**
17	 * A deterministic, non-routable synthetic public IPv4 for a sandbox server,
18	 * drawn from TEST-NET-2 (198.51.100.0/24, RFC 5737 — reserved for docs/examples,
19	 * never routed). Keeps the UI realistic without allocating anything real.
20	 */
21	export function sandboxIp(seed: number): string {
22	  const octet = (Math.abs(Math.trunc(seed)) % 254) + 1;
23	  return `198.51.100.${octet}`;
24	}
25	
26	/** A synthetic locally-administered MAC for a sandbox "dedicated IP". */
27	export function sandboxMac(seed: number): string {
28	  const n = Math.abs(Math.trunc(seed));
29	  const b = (i: number) => ((n >> (i * 5)) & 0xff).toString(16).padStart(2, "0");
30	  return `02:00:${b(0)}:${b(1)}:${b(2)}:${b(3)}`;
31	}
